-- Сид-данные для разработки: 2 tenant, 3 lot, 6 камер, 2 шлагбаума, тарифы, пользователи, смена кассира, правила доступа.
-- Выполняется владельцем схемы (RLS не действует на владельца). Идентификаторы детерминированы.
-- Хеши/шифртексты номеров и ключей здесь — sha256-заглушки: реальные per-tenant HMAC/AES появятся с криптомодулем фазы 3.1,
-- который перегенерирует сид (scripts/seed_dev.py). Пароль пользователей — тоже заглушка (argon2 в фазе 3.2).
BEGIN;




UPDATE parking_lot SET barrier_cidr_allowlist = '{10.10.1.0/24}' WHERE id = '00000000-0000-4000-8000-00000000a101';


   '{"grace_minutes": 15, "first_hour_price": 500000, "price_per_hour": 300000, "daily_max": 3000000, "rounding_mode": "UP", "rounding_step_minutes": 60, "overnight": {"start": "22:00", "end": "07:00", "price_per_hour": 100000}, "weekday_overrides": null}',
   tstzrange('2026-01-01 00:00+05', NULL, '[)'), '00000000-0000-4000-8000-0000000f0001', '00000000-0000-4000-8000-0000000a0001'),
  ('00000000-0000-4000-8000-0000000a1102', '00000000-0000-4000-8000-0000000000a1', '00000000-0000-4000-8000-0000000a1002', 1,
   '{"grace_minutes": 10, "first_hour_price": 1000000, "price_per_hour": 500000, "daily_max": 8000000, "rounding_mode": "UP", "rounding_step_minutes": 30, "overnight": null, "weekday_overrides": null}',
   tstzrange('2026-01-01 00:00+05', NULL, '[)'), NULL, '00000000-0000-4000-8000-0000000a0001'),
  ('00000000-0000-4000-8000-0000000b1101', '00000000-0000-4000-8000-0000000000b1', '00000000-0000-4000-8000-0000000b1001', 1,
   '{"grace_minutes": 30, "first_hour_price": 0, "price_per_hour": 200000, "daily_max": 1500000, "rounding_mode": "NEAREST", "rounding_step_minutes": 15, "overnight": null, "weekday_overrides": {"6": {"price_per_hour": 0}, "0": {"price_per_hour": 0}}}',
   tstzrange('2026-01-01 00:00+05', NULL, '[)'), NULL, '00000000-0000-4000-8000-0000000b0001');


-- правила доступа: blacklist глобальный, VIP на площадке, whitelist со скидкой, абонемент
COMMIT;
